def all_rects(a, minh=4, minw=4):
    Hh,Ww=a.shape; res=set()
    for i in range(Hh):
        for j in range(Ww):
            c=a[i,j]
            w=1
            while j+w<Ww and a[i,j+w]==c:
                # extend width one at a time, compute h for this width
                h=1
                while i+h<Hh and (a[i+1:i+h+1,j:j+w+1]==c).all(): h+=1
                if h>=minh and w+1>=minw: res.add((i,j,h,w+1,int(c)))
                w+=1
            # also w=1 case
            h=1
            while i+h<Hh and (a[i+1:i+h+1,j:j+1]==c).all(): h+=1
            if h>=minh: res.add((i,j,h,1,int(c)))
    return res

def maximal_rects(a, minh=4, minw=4):
    R=list(all_rects(a,minh,minw))
    return [r for r in R if not any(r!=s and s[0]<=r[0] and s[1]<=r[1] and s[0]+s[2]>=r[0]+r[2] and s[1]+s[3]>=r[1]+r[3] for s in R)]

